/** Diagnostic-only CPU timeline. No GL operations, waits or render-thread disk I/O. */
public final class Breakdown {
    public enum Scope {
        UNCLASSIFIED(false), MAIN_FRAME(true), MAIN_LOGIC(true), MAIN_PREP(true), PUBLISH(true), ACQUIRE(true), READY_REGION(false), SLOT_REGION(false),
        PZ_RENDER(true), PZ_WORLD(true), PZ_UI(true), PZ_BUILD(false), INVOKE_QUEUE(true), EVENT_PUMP(true),
        LIMITER(true), OBJECT_WAIT(true), SLEEP(true), YIELD(true), SWAP(true), DISPLAY_UPDATE(true), RESOURCE_GROW(true), PROFILER(false),
        VP_DRAWER(true), VP_PREP(true), VP_WORLD(true), VP_TRANSPARENT(true), VP_WEATHER(true), VP_FINISH(true),
        VP_GBUFFER(false), VP_MODELS(false), VP_FAR(false), VP_PICK(false), RESOURCE(false), RENDER_STEP(true), STEP_ACQUIRE(true), STEP_POST(true), STEP_DISPLAY(true), PZ_PROFILE(true), CONTROLLERS(true), FPS_GRAPH(true), VP_HOOK_START(true), VP_FRAME_START(true), VP_VIDEO_MEMORY(true), VP_MEMORY_CENSUS(true), VP_ONBOARDING(true), VP_HOOK_END(true), VP_FRAME_END(true);
        final boolean cpu; Scope(boolean cpu){this.cpu=cpu;}
    }
    static final Scope[] SCOPES=Scope.values();static final int N=SCOPES.length;
    public static final boolean ENABLED=Options.FRAME_BREAKDOWN&&Options.TELEMETRY.equals("full");
    static final ThreadMXBean CPU=cpuBean();static final AtomicLong SERIAL=new AtomicLong(),LOST=new AtomicLong(),ERRORS=new AtomicLong();
    static final ConcurrentLinkedQueue<Event> QUEUE=new ConcurrentLinkedQueue<>();static final AtomicInteger QUEUED=new AtomicInteger();
    static final ThreadLocal<Lane> LOCAL=ThreadLocal.withInitial(()->{Lane l=new Lane(Thread.currentThread().threadId());offer(l,"thread",Map.of("thread_id",l.thread,"name",Thread.currentThread().getName()));return l;});
    static final ConcurrentHashMap<Long,Long> WINDOWS=new ConcurrentHashMap<>();
    static final ConcurrentHashMap<Object,StateInfo> STATES=new ConcurrentHashMap<>();
    static final ConcurrentHashMap<WeakKey,viewpoint.core.Frame> DRAWER_FRAMES=new ConcurrentHashMap<>();
    static final ConcurrentHashMap<WeakKey,Shot> DRAWERS=new ConcurrentHashMap<>();static final ReferenceQueue<Object> DEAD=new ReferenceQueue<>();
    static volatile boolean healthy=true;
    static ThreadMXBean cpuBean(){if(!ENABLED)return null;try{var b=ManagementFactory.getThreadMXBean();if(!b.isCurrentThreadCpuTimeSupported())return null;if(!b.isThreadCpuTimeEnabled())b.setThreadCpuTimeEnabled(true);return b;}catch(RuntimeException e){return null;}}
    static long cpu(){if(CPU==null)return -1;try{return CPU.getCurrentThreadCpuTime();}catch(RuntimeException e){return -1;}}
    record Event(String kind,Object data){}
    static void offer(Lane l,String kind,Object data){if(!enqueue(new Event(kind,data))){LOST.incrementAndGet();if(l!=null)l.lost++;}}
    static boolean enqueue(Event e){int n;do{n=QUEUED.get();if(n>=4096)return false;}while(!QUEUED.compareAndSet(n,n+1));QUEUE.offer(e);return true;}
    static Event poll(){Event e=QUEUE.poll();if(e!=null)QUEUED.decrementAndGet();return e;}
    static final class Frame {long token,start,cpu,state,shot;int scope;long previousShot;}
    static final class Acc {
        long start,cpuStart,number;final long id,window,generation;long[] inclusive=new long[N],exclusive=new long[N],counts=new long[N],closedCpu=new long[N],cpuSamples=new long[N];long crossBoundaryCpu;
        final LinkedHashSet<Long> states=new LinkedHashSet<>(),shots=new LinkedHashSet<>();long lost,invalid,links,lossStart,expected,snapshotUses,foreignShots;
        Acc(long id,long window,long generation,long start,long cpu){this.id=id;this.window=window;this.generation=generation;this.start=start;this.cpuStart=cpu;lossStart=LOST.get();}
        void reset(long t,long c){start=t;cpuStart=c;Arrays.fill(inclusive,0);Arrays.fill(exclusive,0);Arrays.fill(counts,0);Arrays.fill(closedCpu,0);Arrays.fill(cpuSamples,0);crossBoundaryCpu=0;states.clear();shots.clear();lost=invalid=links=expected=snapshotUses=foreignShots=0;lossStart=LOST.get();}
    }
    static final class Lane {
        final long thread;final Frame[] stack=new Frame[64];int depth;long clock,seq,state,shot,currentWindow,lost,invalid,links;final LinkedHashMap<String,Acc> streams=new LinkedHashMap<>();Acc producer;long aggregateAt,probeNanos,probeCalls;final long[] idleCount=new long[N],idleWall=new long[N],idleCpu=new long[N],idleCpuCount=new long[N];
        Lane(long thread){this.thread=thread;for(int i=0;i<stack.length;i++)stack[i]=new Frame();}
        void tick(long at){if(clock==0){clock=at;return;}if(at<clock){invalid++;return;}long dt=at-clock;clock=at;if(dt==0)return;long mask=0;for(int i=0;i<depth;i++)mask|=1L<<stack[i].scope;int top=depth==0?0:stack[depth-1].scope;
            for(Acc a:streams.values())add(a,dt,mask,top);if(producer!=null)add(producer,dt,mask,top);
        }
        static void add(Acc a,long dt,long mask,int top){a.exclusive[top]+=dt;for(int i=0;i<N;i++)if((mask&(1L<<i))!=0)a.inclusive[i]+=dt;}
        void resource(long start,long end){
            if(start<=0||end<start)return;tick(end);int top=depth==0?0:stack[depth-1].scope;if(top==Scope.RESOURCE.ordinal()||top==Scope.RESOURCE_GROW.ordinal())return;
            boolean included=false;for(int i=0;i<depth;i++)if(stack[i].scope==Scope.RESOURCE.ordinal())included=true;
            for(Acc a:streams.values())attribute(a,start,end,top,included);if(producer!=null)attribute(producer,start,end,top,included);
        }
        void attribute(Acc a,long start,long end,int top,boolean included){long d=Math.max(0,end-Math.max(start,a.start));if(a.exclusive[top]<d){a.invalid++;return;}a.exclusive[top]-=d;a.exclusive[Scope.RESOURCE.ordinal()]+=d;if(!included)a.inclusive[Scope.RESOURCE.ordinal()]+=d;a.counts[Scope.RESOURCE.ordinal()]++;}
        long enter(int scope,long at,long cp){tick(at);if(depth==stack.length){invalid++;return 0;}Frame f=stack[depth++];f.token=++seq;f.start=at;f.cpu=cp;f.scope=scope;f.state=state;f.shot=shot;f.previousShot=shot;
            for(Acc a:streams.values())a.counts[scope]++;if(producer!=null)producer.counts[scope]++;return f.token;}
        void exit(long token,long at,long cp,boolean exceptional){if(token==0)return;tick(at);if(depth==0||stack[depth-1].token!=token){invalid++;depth=0;shot=0;return;}Frame f=stack[--depth];
            if(SCOPES[f.scope].cpu){
                for(Acc a:streams.values())if(f.cpu>=0&&cp>=0){if(f.start>=a.start){a.closedCpu[f.scope]+=cp-f.cpu;a.cpuSamples[f.scope]++;}else a.crossBoundaryCpu++;}
                if(f.scope>=Scope.VP_HOOK_START.ordinal()){shot=f.previousShot;return;}if(f.state==0&&f.shot==0&&!exceptional){idleCount[f.scope]++;idleWall[f.scope]+=at-f.start;if(f.cpu>=0&&cp>=0){idleCpu[f.scope]+=cp-f.cpu;idleCpuCount[f.scope]++;}flushIdle(at,false);}else offer(this,"span",new Span(thread,token,depth==0?0:stack[depth-1].token,f.scope,f.start,at,f.cpu<0||cp<0?-1:cp-f.cpu,f.state,f.shot,exceptional));}shot=f.previousShot;
        }
        void flushIdle(long at,boolean force){if(!force&&at-aggregateAt<1_000_000_000L)return;aggregateAt=at;long count=Arrays.stream(idleCount).sum();if(count==0)return;offer(this,"out_of_state_scopes",Map.of("thread_id",thread,"end_ns",at,"calls",idleCount.clone(),"inclusive_wall_ns",idleWall.clone(),"cpu_ns",idleCpu.clone(),"cpu_samples",idleCpuCount.clone()));Arrays.fill(idleCount,0);Arrays.fill(idleWall,0);Arrays.fill(idleCpu,0);Arrays.fill(idleCpuCount,0);}
        Map<String,Object> boundary(long window,long generation,long at,long cp,long legacy,boolean primary){tick(at);String key=window+":"+generation;Acc a=streams.get(key);if(a==null){if(streams.size()>=8){invalid++;return Map.of("first_partial",true,"overflow",true);}a=new Acc(SERIAL.incrementAndGet(),window,generation,at,cp);streams.put(key,a);return interval(a,at,cp,legacy,primary,true);}
            Map<String,Object> row=interval(a,at,cp,legacy,primary,false);a.number++;a.reset(at,cp);return row;
        }
        Map<String,Object> interval(Acc a,long at,long cp,long legacy,boolean primary,boolean first){long wall=first?0:at-a.start;long covered=Arrays.stream(a.exclusive).sum();Map<String,Object> m=new LinkedHashMap<>();m.put("probe_wall_ns",probeNanos);m.put("probe_calls",probeCalls);probeNanos=probeCalls=0;m.put("stream_id",a.id);m.put("window",a.window);m.put("window_generation",a.generation);m.put("thread_id",thread);m.put("interval_id",first?0:a.number+1);m.put("legacy_frame",legacy);m.put("primary",primary);m.put("start_ns",a.start);m.put("end_ns",at);m.put("wall_ns",wall);long ownCpu=a.cpuStart<0||cp<0?-1:cp-a.cpuStart;m.put("cpu_ns",ownCpu<0?null:ownCpu);m.put("off_cpu_ns",ownCpu>=0&&ownCpu<=wall?wall-ownCpu:null);m.put("cpu_status",ownCpu<0?"unavailable":ownCpu>wall?"sample_boundary_mismatch":"available");m.put("exclusive_ns",a.exclusive.clone());m.put("inclusive_ns",a.inclusive.clone());m.put("calls",a.counts.clone());m.put("closed_scope_cpu_ns",a.closedCpu.clone());m.put("closed_scope_cpu_samples",a.cpuSamples.clone());m.put("cross_boundary_cpu_scopes",a.crossBoundaryCpu);m.put("state_generations",List.copyOf(a.states));m.put("snapshots",List.copyOf(a.shots));m.put("snapshot_count",a.shots.size());m.put("snapshot_status",a.shots.isEmpty()?"none":a.shots.size()==1?"one":"multiple");m.put("first_partial",first);m.put("coverage_error_ns",first?0:covered-wall);m.put("lost_events",LOST.get()-a.lossStart);m.put("invalid_scopes",invalid+a.invalid);m.put("unknown_links",links+a.links);m.put("missing_snapshots",Math.max(0,a.expected-a.snapshotUses));m.put("snapshot_uses",a.snapshotUses);m.put("foreign_window_snapshots",a.foreignShots);m.put("open_tokens",java.util.stream.IntStream.range(0,depth).mapToObj(i->stack[i].token).toList());m.put("timing_complete",!first&&covered==wall&&LOST.get()==a.lossStart&&invalid+a.invalid==0);m.put("association_complete",links+a.links==0&&a.expected<=a.snapshotUses&&a.foreignShots==0);lost=invalid=links=0;return m;}
        void associate(long gen,long snap){for(Acc a:streams.values()){if(gen>0){if(a.states.size()<64)a.states.add(gen);else a.links++;}if(snap>0){if(currentWindow!=a.window)a.foreignShots++;if(a.shots.size()<64)a.shots.add(snap);else a.links++;}}}
    }
    record Span(long thread,long token,long parent,int scope,long start,long end,long cpu,long state,long shot,boolean exceptional){}
    static final class StateInfo {final long generation,producer;final AtomicInteger uses=new AtomicInteger(),expected=new AtomicInteger();volatile boolean published;StateInfo(long gen,long tid){generation=gen;producer=tid;}}
    static final class WeakKey extends WeakReference<Object>{final int hash;WeakKey(Object x,ReferenceQueue<Object> q){super(x,q);hash=System.identityHashCode(x);}public int hashCode(){return hash;}public boolean equals(Object x){return x instanceof WeakKey k&&(this==k||(get()!=null&&get()==k.get()));}}
    record Shot(long id,long number,long taken,long state,AtomicInteger uses){}
    static void resource(long start,long end){if(enabled())LOCAL.get().resource(start,end);}
    public static void warmup(){if(ENABLED)cpu();}
    static boolean enabled(){return ENABLED&&!ReleaseLogs.capped&&healthy;}
    public static long open(int scope){if(!enabled())return 0;try{long begin=System.nanoTime();Lane l=LOCAL.get();long token=l.enter(scope,begin,SCOPES[scope].cpu?cpu():-1);l.probeCalls++;l.probeNanos+=System.nanoTime()-begin;return token;}catch(RuntimeException e){ERRORS.incrementAndGet();healthy=false;return 0;}}
    public static void close(long token){closeAt(token,System.nanoTime(),false);}
    public static void exceptional(long token){closeAt(token,System.nanoTime(),true);}
    static void closeAt(long token,long at,boolean exceptional){if(token==0||!enabled())return;try{long begin=System.nanoTime();Lane l=LOCAL.get();int s=l.depth==0?0:l.stack[l.depth-1].scope;l.exit(token,at,SCOPES[s].cpu?cpu():-1,exceptional);l.probeCalls++;l.probeNanos+=System.nanoTime()-begin;}catch(RuntimeException e){ERRORS.incrementAndGet();healthy=false;}}
    static long profiler(long at){return enabled()?LOCAL.get().enter(Scope.PROFILER.ordinal(),at,-1):0;}
    // Call-site wrappers bracket later agents' method-entry/exit advice as well as our method scopes.
    // Exception cleanup lives here, so the original method's existing catch-table precedence is unchanged.
    public static zombie.core.sprite.SpriteRenderState stepAcquire(zombie.core.SpriteRenderer renderer,java.util.function.BooleanSupplier supplier){long t=open(Scope.STEP_ACQUIRE.ordinal());try{return renderer.acquireStateForRendering(supplier);}finally{close(t);}}
    public static void stepPost(zombie.core.SpriteRenderer renderer){long t=open(Scope.STEP_POST.ordinal());try{renderer.postRender();}finally{close(t);}}
    public static void stepDisplay(boolean process){long t=open(Scope.STEP_DISPLAY.ordinal());try{org.lwjglx.opengl.Display.update(process);}finally{close(t);}}
    public static zombie.core.profiling.AbstractPerformanceProfileProbe stepProfile(zombie.core.profiling.PerformanceProfileProbe probe){long t=open(Scope.PZ_PROFILE.ordinal());try{return probe.profile();}finally{close(t);}}
    public static void stepProfileClose(zombie.core.profiling.AbstractPerformanceProfileProbe probe){long t=open(Scope.PZ_PROFILE.ordinal());try{probe.close();}finally{close(t);}}
    public static void waitObject(Object object)throws InterruptedException{long t=open(Scope.OBJECT_WAIT.ordinal());boolean ok=false;try{object.wait();ok=true;}finally{if(ok)close(t);else exceptional(t);}}
    public static void waitObject(Object object,long ms)throws InterruptedException{long t=open(Scope.OBJECT_WAIT.ordinal());boolean ok=false;try{object.wait(ms);ok=true;}finally{if(ok)close(t);else exceptional(t);}}
    public static void waitObject(Object object,long ms,int ns)throws InterruptedException{long t=open(Scope.OBJECT_WAIT.ordinal());boolean ok=false;try{object.wait(ms,ns);ok=true;}finally{if(ok)close(t);else exceptional(t);}}
    public static void sleep(long ms)throws InterruptedException{long t=open(Scope.SLEEP.ordinal());boolean ok=false;try{Thread.sleep(ms);ok=true;}finally{if(ok)close(t);else exceptional(t);}}
    public static void yieldThread(){long t=open(Scope.YIELD.ordinal());try{Thread.yield();}finally{close(t);}}
    public static void populate(Object state){if(!enabled())return;Lane l=LOCAL.get();if(STATES.size()>=64&&!STATES.containsKey(state)){l.links++;return;}StateInfo info=new StateInfo(SERIAL.incrementAndGet(),l.thread);STATES.put(state,info);l.tick(System.nanoTime());l.state=info.generation;l.producer=new Acc(0,0,0,l.clock,cpu());offer(l,"state",Map.of("event","populate","generation",info.generation,"thread_id",l.thread,"time_ns",l.clock));}
    public static void publish(Object state){if(!enabled())return;Lane l=LOCAL.get();StateInfo info=STATES.get(state);if(info==null){l.links++;return;}info.published=true;long at=System.nanoTime();l.tick(at);offer(l,"state",Map.of("event","publish","generation",info.generation,"thread_id",l.thread,"time_ns",at));if(l.producer!=null){offer(l,"producer_batch",Map.of("generation",info.generation,"thread_id",l.thread,"start_ns",l.producer.start,"end_ns",at,"exclusive_ns",l.producer.exclusive.clone(),"inclusive_ns",l.producer.inclusive.clone()));l.producer=null;}if(l.thread==info.producer)l.state=0;}
    public static void consume(Object state){if(!enabled())return;Lane l=LOCAL.get();StateInfo info=STATES.get(state);if(info==null){l.links++;l.state=0;offer(l,"state",Map.of("event","consume_unknown","thread_id",l.thread,"time_ns",System.nanoTime()));return;}int used=info.uses.incrementAndGet();l.state=info.generation;l.associate(l.state,0);for(Acc a:l.streams.values())a.expected+=info.expected.get();if(!info.published)l.links++;offer(l,"state",Map.of("event","consume","generation",info.generation,"producer_thread",info.producer,"thread_id",l.thread,"time_ns",System.nanoTime(),"repeat",used>1,"published",info.published));}
    public static void drawerCreated(Object drawer,viewpoint.core.Frame frame){if(!enabled())return;if(frame==null){LOCAL.get().links++;return;}long number=frame.number,taken=frame.takenNanos;Lane l=LOCAL.get();for(int i=0;i<32;i++){Reference<?> r=DEAD.poll();if(r==null)break;DRAWERS.remove(r);DRAWER_FRAMES.remove(r);}if(DRAWERS.size()>=2048){l.links++;return;}Shot s=new Shot(SERIAL.incrementAndGet(),number,taken,l.state,new AtomicInteger());DRAWERS.put(new WeakKey(drawer,DEAD),s);for(StateInfo i:STATES.values())if(i.generation==l.state){i.expected.incrementAndGet();break;}offer(l,"snapshot",Map.of("event","created","snapshot_id",s.id,"vp_number",number,"taken_ns",taken,"producer_generation",l.state,"thread_id",l.thread,"time_ns",System.nanoTime()));}
    public static long drawerBegin(Object drawer,viewpoint.core.Frame frame){if(!enabled())return 0;long number=frame==null?-1:frame.number,taken=frame==null?-1:frame.takenNanos;Lane l=LOCAL.get();Shot s=DRAWERS.get(new WeakKey(drawer,null));boolean valid=s!=null&&s.number==number&&s.taken==taken&&s.state!=0&&s.state==l.state;if(!valid)l.links++;long token=open(Scope.VP_DRAWER.ordinal());if(valid){l.shot=s.id;if(l.depth>0)l.stack[l.depth-1].shot=s.id;l.associate(l.state,s.id);for(Acc a:l.streams.values())a.snapshotUses++;}Map<String,Object> m=new LinkedHashMap<>();m.put("event","used");m.put("snapshot_id",valid?s.id:null);m.put("candidate_snapshot_id",s==null?null:s.id);m.put("vp_number",number);m.put("taken_ns",taken);m.put("producer_generation",s==null?null:s.state);m.put("render_generation",l.state);m.put("render_window",l.currentWindow);m.put("thread_id",l.thread);m.put("time_ns",System.nanoTime());m.put("valid",valid);m.put("link_reason",valid?"matched":s==null?"missing_publication":s.number!=number||s.taken!=taken?"frame_mutated":s.state==0?"unknown_producer_state":"state_generation_mismatch");m.put("repeat",s!=null&&s.uses.incrementAndGet()>1);offer(l,"snapshot",m);return token;}
    public static void rendered(Object state){if(enabled()){Lane l=LOCAL.get();StateInfo i=STATES.get(state);if(i!=null&&i.generation==l.state)l.state=0;}}
    public static void drawerRegistered(Object drawer,viewpoint.core.Frame frame){if(!enabled()||frame==null)return;if(DRAWER_FRAMES.size()<2048)DRAWER_FRAMES.put(new WeakKey(drawer,DEAD),frame);else LOCAL.get().links++;}
    /** Called at the actual FP.renderWorld drawGeneric enqueue, after snapshot has completed. */
    public static void drawerQueued(Object drawer){if(!enabled())return;viewpoint.core.Frame frame=DRAWER_FRAMES.get(new WeakKey(drawer,null));if(frame==null){LOCAL.get().links++;return;}drawerCreated(drawer,frame);}
    public static void drawerReleased(Object drawer){/* pooled drawer/frame lifetime spans postRender; next enqueue replaces the publication */}
    public static void windowCreated(long window){if(window!=0)WINDOWS.put(window,SERIAL.incrementAndGet());}
    public static void windowDestroyed(long window){WINDOWS.remove(window);String key=PRIMARY.get();if(key!=null&&key.startsWith(window+":"))PRIMARY.compareAndSet(key,null);if(enabled())LOCAL.get().streams.values().removeIf(a->a.window==window);}
    public static void currentWindow(long window){if(enabled()){Lane l=LOCAL.get();if(l.currentWindow!=window)offer(l,"context",Map.of("thread_id",l.thread,"window",window,"window_generation",WINDOWS.getOrDefault(window,0L),"time_ns",System.nanoTime()));l.currentWindow=window;}}
    static final AtomicReference<String> PRIMARY=new AtomicReference<>();static int primary(long window){String key=window+":"+WINDOWS.getOrDefault(window,0L)+":"+Thread.currentThread().threadId();if(PRIMARY.compareAndSet(null,key))return 2;return PRIMARY.get().equals(key)?1:0;}
    static boolean firstStream(long window){return enabled()&&!LOCAL.get().streams.containsKey(window+":"+WINDOWS.getOrDefault(window,0L));}
    static void boundary(long window,long end,long cp,long legacy,boolean primary){if(!enabled())return;Lane l=LOCAL.get();long gen=WINDOWS.getOrDefault(window,0L);l.flushIdle(end,true);offer(l,"interval",l.boundary(window,gen,end,cp,legacy,primary));}
    static boolean pending(){return ENABLED&&!QUEUE.isEmpty();}
    static Map<String,Object> metadata(){return Map.of("schema",3,"enabled",ENABLED,"cpu_available",CPU!=null,"clock","System.nanoTime ns; current-thread CPU ns","scopes",Arrays.stream(SCOPES).map(Enum::name).toList(),"nesting","exclusive is non-overlapping on each output thread; inclusive union per scope; parallel producer work is separate","cpu_rule","whole closed scopes are not proportionally clipped; interval CPU sampled on its owning thread; out-of-state scopes aggregated per thread/scope at most once per second; probe_wall_ns is inclusive measurement overhead, not an additional interval category; closed_scope_cpu_ns/samples contain only whole scopes completed inside this interval, cross-boundary scopes are counted separately; seven VP hook scopes emit frame aggregates only","limits",Map.of("queue",4096,"stack",64,"windows_per_thread",8,"states",64,"drawers",2048,"ids_per_interval",64));}
    static Sink sink(Path recording)throws IOException{return new Sink(recording);}
    static final class Sink implements AutoCloseable {
        final BufferedWriter writer;final Path summary;final ArrayDeque<Map<String,Object>> recent=new ArrayDeque<>();final PriorityQueue<Map<String,Object>> slow=new PriorityQueue<>(Comparator.comparingLong(x->((Number)x.get("wall_ns")).longValue()));long intervals,complete,incomplete,timingIncomplete,associationIncomplete,activeCount,activeWall,activeMax,wallTotal,max,spans,first;final ArrayDeque<Long> activeRecent=new ArrayDeque<>();final Map<String,CpuStats> cpuStats=new LinkedHashMap<>();long next;final long[] scopeTotal=new long[N],scopeMax=new long[N];
        Sink(Path file)throws IOException{summary=file.resolveSibling(file.getFileName()+".breakdown-summary.json");writer=ENABLED?Files.newBufferedWriter(file.resolveSibling(file.getFileName()+".breakdown.jsonl")):null;if(writer!=null){writer.write(json(Map.of("type","metadata","data",metadata())));writer.newLine();}}
        @SuppressWarnings("unchecked") void drain()throws IOException{if(writer==null)return;if(ReleaseLogs.capped){while(poll()!=null){}return;}Event e;int n=0;while(n++<1024&&(e=poll())!=null){Object data=e.data;if(data instanceof Span s){Map<String,Object> m=new LinkedHashMap<>();m.put("thread_id",s.thread);m.put("token",s.token);m.put("parent_token",s.parent);m.put("scope",SCOPES[s.scope].name());m.put("start_ns",s.start);m.put("end_ns",s.end);m.put("wall_ns",s.end-s.start);m.put("cpu_ns",s.cpu<0?null:s.cpu);m.put("state_generation",s.state);m.put("snapshot_id",s.shot==0?null:s.shot);m.put("exceptional",s.exceptional);data=m;spans++;String key=s.thread+":"+s.scope;if(cpuStats.size()<512||cpuStats.containsKey(key))cpuStats.computeIfAbsent(key,k->new CpuStats(s.thread,s.scope)).add(s.end-s.start,s.cpu);}writer.write(json(Map.of("type",e.kind,"data",data)));writer.newLine();if(e.kind.equals("interval"))accept((Map<String,Object>)data);}
            if(System.nanoTime()>=next){writeSummary();writer.flush();next=System.nanoTime()+2_000_000_000L;}}
        void accept(Map<String,Object> m){if(!Boolean.TRUE.equals(m.get("primary")))return;if(Boolean.TRUE.equals(m.get("first_partial"))){first++;return;}intervals++;if(!Boolean.TRUE.equals(m.get("timing_complete")))timingIncomplete++;if(!Boolean.TRUE.equals(m.get("association_complete")))associationIncomplete++;if(!Boolean.TRUE.equals(m.get("timing_complete"))||!Boolean.TRUE.equals(m.get("association_complete"))){incomplete++;return;}complete++;long dt=((Number)m.get("wall_ns")).longValue();wallTotal+=dt;max=Math.max(max,dt);if(((Number)m.get("snapshot_count")).intValue()>0){activeCount++;activeWall+=dt;activeMax=Math.max(activeMax,dt);activeRecent.addLast(dt);if(activeRecent.size()>8192)activeRecent.removeFirst();}recent.addLast(m);if(recent.size()>8192)recent.removeFirst();long[] x=(long[])m.get("exclusive_ns");for(int i=0;i<N;i++){scopeTotal[i]+=x[i];scopeMax[i]=Math.max(scopeMax[i],x[i]);}slow.add(m);if(slow.size()>20)slow.poll();}
        void writeSummary()throws IOException{long[] v=recent.stream().mapToLong(x->((Number)x.get("wall_ns")).longValue()).sorted().toArray();Map<String,Object> m=new LinkedHashMap<>();m.put("schema",1);m.put("stream_scope","primary only; other streams remain separate in JSONL/offline report");m.put("intervals",intervals);m.put("complete",complete);m.put("incomplete",incomplete);m.put("first_partial",first);m.put("mean_ns",complete==0?null:(double)wallTotal/complete);m.put("max_ns",max);m.put("p95_ns",percentile(v,.95));m.put("p99_ns",percentile(v,.99));m.put("quantile_scope","last 8192 complete intervals; means/max/top20 entire recording; use offline analyzer for exact session quantiles");m.put("lost_events",LOST.get());m.put("diagnostic_errors",ERRORS.get());m.put("healthy",healthy);m.put("collector_operational",healthy);m.put("trace_lossless",LOST.get()==0);m.put("timing_incomplete",timingIncomplete);m.put("association_incomplete",associationIncomplete);m.put("associations_complete",associationIncomplete==0);long[] av=activeRecent.stream().mapToLong(Long::longValue).sorted().toArray();Map<String,Object> active=new LinkedHashMap<>();active.put("selection","complete primary intervals containing a published Viewpoint snapshot; not geographic/game-state classification");active.put("count",activeCount);active.put("mean_ns",activeCount==0?null:(double)activeWall/activeCount);active.put("max_ns",activeMax);active.put("p95_ns",percentile(av,.95));active.put("p99_ns",percentile(av,.99));m.put("viewpoint_intervals",active);m.put("session_integrity_complete",healthy&&LOST.get()==0&&incomplete==0);m.put("selection","all primary intervals including menus/loading; not a game-only FPS sample");m.put("cpu_span_records",spans);m.put("closed_scope_cpu",cpuStats.values().stream().map(CpuStats::summary).toList());List<Map<String,Object>> parts=new ArrayList<>();for(int i=0;i<N;i++){long[] q=new long[recent.size()];int at=0;for(var r:recent)q[at++]=((long[])r.get("exclusive_ns"))[i];Arrays.sort(q);Map<String,Object> p=new LinkedHashMap<>();p.put("scope",SCOPES[i].name());p.put("mean_exclusive_ns",complete==0?null:(double)scopeTotal[i]/complete);p.put("p95_exclusive_ns",percentile(q,.95));p.put("p99_exclusive_ns",percentile(q,.99));p.put("max_exclusive_ns",scopeMax[i]);parts.add(p);}m.put("exclusive_scopes",parts);m.put("slowest20",slow.stream().sorted(Comparator.comparingLong(x->-((Number)x.get("wall_ns")).longValue())).toList());Path tmp=summary.resolveSibling(summary.getFileName()+".tmp");Files.writeString(tmp,json(m)+"\n");Files.move(tmp,summary,StandardCopyOption.REPLACE_EXISTING);}
        public void close()throws IOException{if(writer==null)return;while(!QUEUE.isEmpty())drain();writeSummary();writer.close();}
    }
    static final class CpuStats {
        final long thread;final int scope;long count,cpuCount,wallSum,cpuSum,wallMax,cpuMax;final long[] values=new long[4096];
        CpuStats(long thread,int scope){this.thread=thread;this.scope=scope;}
        void add(long wall,long cpu){count++;wallSum+=wall;wallMax=Math.max(wallMax,wall);if(cpu>=0){values[(int)(cpuCount++%values.length)]=cpu;cpuSum+=cpu;cpuMax=Math.max(cpuMax,cpu);}}
        Map<String,Object> summary(){long[] v=Arrays.copyOf(values,(int)Math.min(cpuCount,values.length));Arrays.sort(v);Map<String,Object> m=new LinkedHashMap<>();m.put("thread_id",thread);m.put("scope",SCOPES[scope].name());m.put("closed_spans",count);m.put("cpu_samples",cpuCount);m.put("mean_inclusive_wall_ns",count==0?null:(double)wallSum/count);m.put("mean_inclusive_cpu_ns",cpuCount==0?null:(double)cpuSum/cpuCount);m.put("p95_cpu_ns",percentile(v,.95));m.put("p99_cpu_ns",percentile(v,.99));m.put("max_cpu_ns",cpuMax);m.put("max_wall_ns",wallMax);m.put("cpu_quantile_scope","last 4096 samples per thread/scope; parent/child CPU must not be added");return m;}
    }
    static Object percentile(long[] v,double q){return v.length==0?null:v[(int)Math.ceil(v.length*q)-1];}
    /** Called only by the background sink/tests. */
    static String json(Object v){if(v==null)return "null";if(v instanceof Number||v instanceof Boolean)return v.toString();if(v instanceof String s)return '"'+s.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\r","\\r")+'"';if(v instanceof Map<?,?> m){StringJoiner j=new StringJoiner(",","{","}");for(var e:m.entrySet())j.add(json(e.getKey().toString())+":"+json(e.getValue()));return j.toString();}if(v instanceof Iterable<?> a){StringJoiner j=new StringJoiner(",","[","]");for(var x:a)j.add(json(x));return j.toString();}if(v instanceof long[] a)return Arrays.toString(a);throw new IllegalArgumentException(v.getClass().toString());}
}
